def longest_subarray(nums, limit):
    n = len(nums)
    best = 0
    for i in range(n):
        window_max = nums[i]
        window_min = nums[i]
        for j in range(i, n):                                              # extend the window one element at a time
            window_max = max(window_max, nums[j])
            window_min = min(window_min, nums[j])
            if window_max - window_min <= limit:
                best = max(best, j - i + 1)
            else:
                break                                                       # this window (and any longer one starting at i) is invalid
    return best


if __name__ == "__main__":
    print(longest_subarray([10, 1, 2, 4, 7, 2], 5))

