import java.util.*;

public class Main {
    int longestSubarray(int[] nums, int limit) {
        Deque<Integer> maxDeque = new ArrayDeque<>();                                // DECREASING deque of indices: front is always the window's max
        Deque<Integer> minDeque = new ArrayDeque<>();                                // INCREASING deque of indices: front is always the window's min
        int left = 0, best = 0;
        for (int right = 0; right < nums.length; right++) {
            while (!maxDeque.isEmpty() && nums[maxDeque.peekLast()] <= nums[right]) {   // maintain decreasing order: pop anything <= the new value
                maxDeque.pollLast();
            }
            maxDeque.addLast(right);
            while (!minDeque.isEmpty() && nums[minDeque.peekLast()] >= nums[right]) {   // maintain increasing order: pop anything >= the new value
                minDeque.pollLast();
            }
            minDeque.addLast(right);

            while (nums[maxDeque.peekFirst()] - nums[minDeque.peekFirst()] > limit) {   // window invalid: shrink from the LEFT
                left++;
                if (maxDeque.peekFirst() < left) maxDeque.pollFirst();
                if (minDeque.peekFirst() < left) minDeque.pollFirst();
            }

            best = Math.max(best, right - left + 1);
        }
        return best;
    }

    public static void main(String[] args) {
        Main solution = new Main();
        int[] nums = {8, 2, 4, 7};
        System.out.println(solution.longestSubarray(nums, 4));
    }
}

