#include <bits/stdc++.h>
using namespace std;

int longestSubarray(vector<int>& nums, int limit) {
    deque<int> maxDeque, minDeque;                                                     // DECREASING / INCREASING deques of indices for window max/min
    int left = 0, best = 0;
    for (int right = 0; right < (int)nums.size(); right++) {
        while (!maxDeque.empty() && nums[maxDeque.back()] <= nums[right]) {               // maintain decreasing order: pop anything <= the new value
            maxDeque.pop_back();
        }
        maxDeque.push_back(right);
        while (!minDeque.empty() && nums[minDeque.back()] >= nums[right]) {               // maintain increasing order: pop anything >= the new value
            minDeque.pop_back();
        }
        minDeque.push_back(right);

        while (nums[maxDeque.front()] - nums[minDeque.front()] > limit) {                 // window invalid: shrink from the LEFT
            left++;
            if (maxDeque.front() < left) maxDeque.pop_front();
            if (minDeque.front() < left) minDeque.pop_front();
        }

        best = max(best, right - left + 1);
    }
    return best;
}

int main() {
    vector<int> nums = {8, 2, 4, 7};
    cout << longestSubarray(nums, 4) << endl;
    return 0;
}
